  template<typename _CharT>
    __timepunct<_CharT>::__timepunct(__cache_type* __cache, size_t __refs) 
    : facet(__refs), _M_data(__cache)
    { 
      _M_name_timepunct = _S_get_c_name();
      _M_initialize_timepunct(); 
